export const meta = { name: 'spike-stop-wf', description: 'spike: two sleeping agents', phases: [{ title: 'Sleep' }, { title: 'Report' }] }
phase('Sleep')
const rs = await parallel([1, 2].map((i) => () => agent("Use the Bash tool to run exactly: perl -e 'sleep 80'  (timeout 90000). After it finishes reply with the single word DONE.", { label: 'sleep:' + i, phase: 'Sleep' })))
phase('Report')
return { rs }
